pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero budget is invalid according to the configuration contract; make
    // it behave as one attempt so the function always returns a job result.
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;
    let mut delay = config.base_delay_ms;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempt < max_attempts => {
                sleeper.sleep_ms(delay.min(config.max_delay_ms));
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
            Err(error) => return Err(error),
        }
    }
}

